#!/usr/bin/env node
/**
 * Generates src/environment.ts from the repo root .env, the same way
 * generate-theme-palette.cjs generates the brand palette — one source of
 * truth, regenerated rather than hand-duplicated.
 *
 * The three Auth0 values here are NOT secrets: this is a public SPA client
 * using Authorization Code + PKCE, so the Domain/Client ID/Audience are
 * meant to be visible in the shipped JS bundle (unlike a client secret,
 * which a SPA never has). Baking them in at build time is the standard
 * Auth0 SPA pattern, not a shortcut.
 *
 * The generated file is gitignored (like .env itself) and regenerated by
 * each developer locally — see the `pretest`/`prestart`/`prebuild` hooks in
 * package.json that run this automatically.
 */
const { config } = require('dotenv');
const fs = require('node:fs');
const path = require('node:path');

const ROOT_ENV = path.join(__dirname, '../../../.env');
const LOCAL_ENV = path.join(__dirname, '../.env');
const OUT_FILE = path.join(__dirname, '../src/environment.ts');

config({ path: [ROOT_ENV, LOCAL_ENV], quiet: true });

function required(name) {
  const value = process.env[name];
  if (!value) {
    throw new Error(
      `${name} is not set in .env. Copy .env.example to .env and fill in your Auth0 values ` +
        `(see README's "Auth0 setup" section) before running the web app.`,
    );
  }
  return value;
}

const domain = required('AUTH0_DOMAIN');
const clientId = required('AUTH0_CLIENT_ID');
const audience = required('AUTH0_AUDIENCE');

const out = `// GENERATED FILE — do not hand-edit. Regenerate with:
//   node scripts/generate-environment.cjs
// (this also runs automatically before \`npm start\`/\`build\`/\`test\`)
export const environment = {
  auth0: {
    domain: ${JSON.stringify(domain)},
    clientId: ${JSON.stringify(clientId)},
    audience: ${JSON.stringify(audience)},
  },
} as const;
`;

fs.writeFileSync(OUT_FILE, out);
console.log(`Wrote ${OUT_FILE}`);
